@if($canonReview)
    <p class="sandbox-notice">Review {{ count($canonReview['changes']) }} record changes. Acceptance updates the live world, not finished drafts or published prose.</p>
    @foreach($canonReview['changes'] as $change)<section class="sandbox-review-change"><h3>{{ $change['target_key'] ? 'Update' : 'Create' }} {{ $change['kind'] }}: {{ $change['title'] }}</h3>@if($change['before'])<details open><summary>Current record</summary><dl>@foreach(collect($change['before'])->only(array_keys($change['after'])) as $key=>$value)<dt>{{ str_replace('_',' ',$key) }}</dt><dd>{{ is_array($value) ? json_encode($value,JSON_UNESCAPED_UNICODE) : $value }}</dd>@endforeach</dl></details>@endif<details open><summary>Proposed content</summary><dl>@foreach($change['after'] as $key=>$value)<dt>{{ str_replace('_',' ',$key) }}</dt><dd>{{ is_array($value) ? json_encode($value,JSON_UNESCAPED_UNICODE) : $value }}</dd>@endforeach</dl></details></section>@endforeach
    @if($canonReview['links'])<h3>Connections in this review</h3>@foreach($canonReview['links'] as $link)<p>{{ $ideas->firstWhere('id',$link['source_id'])?->title }} → {{ $ideas->firstWhere('id',$link['target_id'])?->title }}: {{ $link['label'] }} ({{ $link['kind'] }})</p>@endforeach @endif
    <flux:button variant="primary" icon="check-badge" wire:click="acceptCanon" wire:loading.attr="disabled">Make these changes canon</flux:button>
@else<p>Select record proposals on the board or list, then choose Review canon. Questions and shortlists stay in the sandbox.</p>@endif
